function draw(){let w=canvas.width,h=canvas.height,z=game.zone(),night=game.state.timeOfDay==='night',rain=game.state.weather==='rain',g=ctx.createLinearGradient(0,0,0,h);let scene=ZONE_SCENE_PROFILES[z.id]||ZONE_SCENE_PROFILES.pond;g.addColorStop(0,night?scene.skyNight:scene.skyDay);g.addColorStop(.56,night?scene.waterNight:scene.waterDay);g.addColorStop(.58,night?scene.waterNight:scene.waterDay);g.addColorStop(1,night?scene.deepNight:scene.deepDay);ctx.fillStyle=g;ctx.fillRect(0,0,w,h);if(night){ctx.fillStyle='rgba(231,238,255,.68)';for(let i=0;i<42;i++){let sx=(i*173+31)%w,sy=(i*67+17)%(h*.42);ctx.fillRect(sx,sy,1.6,1.6)}ctx.fillStyle='#e4e8f5';ctx.beginPath();ctx.arc(w*.82,h*.15,22,0,Math.PI*2);ctx.fill();ctx.fillStyle='#203d5c';ctx.beginPath();ctx.arc(w*.835,h*.135,21,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#ffe8a0';ctx.beginPath();ctx.arc(w*.82,h*.15,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='rgba(255,232,160,.12)';ctx.beginPath();ctx.arc(w*.82,h*.15,37,0,Math.PI*2);ctx.fill()}if(rain){ctx.strokeStyle='rgba(202,231,255,.35)';ctx.lineWidth=1;for(let i=0;i<58;i++){let rx=(i*137+clock*180)%w,ry=(i*83+clock*310)%(h*.58);ctx.beginPath();ctx.moveTo(rx,ry);ctx.lineTo(rx-3,ry+13);ctx.stroke()}}ctx.fillStyle='#071b29';ctx.beginPath();ctx.moveTo(0,h*.57);for(let x=0;x<=w;x+=80)ctx.lineTo(x,h*.52+Math.sin(x*.012+clock)*15);ctx.lineTo(w,h*.64);ctx.lineTo(0,h*.64);ctx.fill();drawZoneLandmarks(z,w,h,night,clock);drawHiddenGoopSigns(w,h,clock);drawHiddenGoopReveal();drawHiddenCatchCelebration();for(let i=0;i<30;i++){let x=(i*73+clock*26)%w,y=h*.65+(i*27)%h*.27;ctx.strokeStyle='rgba(130,224,220,.14)';ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+20+Math.sin(clock+i)*8,y);ctx.stroke()}for(let x=15;x<w;x+=34){ctx.strokeStyle='#3b735d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(x,h*.62);ctx.quadraticCurveTo(x-8,h*.48,x+Math.sin(x)*8,h*.43);ctx.stroke()}ctx.strokeStyle='#c6a47b';ctx.lineWidth=9;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(w*.13,h*.82);ctx.quadraticCurveTo(w*.2,h*.24,w*.57,h*.4);ctx.stroke();ctx.strokeStyle='#ded0a5';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(w*.57,h*.4);ctx.lineTo(w*.69,h*.68);ctx.stroke();let bob=h*.68+Math.sin(clock*2.5)*4;ctx.fillStyle='#ffbd63';ctx.beginPath();ctx.arc(w*.69,bob,10,0,Math.PI*2);ctx.fill();if(game.phase===PHASES.BITE){ctx.strokeStyle='#fff4a2';ctx.lineWidth=3;ctx.beginPath();ctx.arc(w*.69,bob,25+Math.sin(clock*10)*5,0,Math.PI*2);ctx.stroke()}if(game.fish&&[PHASES.FIGHT,PHASES.CAUGHT].includes(game.phase)){let f=game.fish,fight=game.fight,move=fight?.currentMove,moveState=fight?.moveState||'idle',scale=fight?.specimen?.sizeScale||1,pulse=(Math.sin(clock*10)+1)/2,x=w*.72+(moveState==='active'?Math.sin(clock*13)*13:0),y=h*.79+Math.sin(clock*4)*9+(moveState==='active'&&move?.id==='dive'?14:0),tilt=moveState==='active'?(move?.id==='headshake'?Math.sin(clock*28)*.5:Math.sin(clock*13)*.18):Math.sin(clock)*.25;if(move&&moveState==='tell'){ctx.strokeStyle='rgba(244,196,110,'+(.25+pulse*.55)+')';ctx.lineWidth=3;ctx.beginPath();ctx.arc(x,y,43+pulse*8,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#f4c46e';ctx.font='bold 15px system-ui';ctx.textAlign='center';ctx.fillText('!',x,y-48)}if(move&&moveState==='active'){for(let i=0;i<4;i++){ctx.fillStyle='rgba(150,225,225,'+(.18+pulse*.12)+')';ctx.beginPath();ctx.arc(x-28+i*18,y+30+(i%2)*9,3+(i%2),0,Math.PI*2);ctx.fill()}}drawCreature(x,y,f,scale,tilt,visualFor(f),clock)}}
function conditionsUI(){let time=game.state.timeOfDay||'day',weather=game.state.weather||'clear';document.querySelectorAll('[data-time],[data-weather]').forEach(b=>b.disabled=!game.canPrepare());$('conditionsName').textContent=(time==='night'?'Night':'Day')+' · '+(weather==='rain'?'Rain':'Clear');document.querySelectorAll('[data-time]').forEach(b=>b.classList.toggle('selected',b.dataset.time===time));document.querySelectorAll('[data-weather]').forEach(b=>b.classList.toggle('selected',b.dataset.weather===weather));}
