function loop(ts){let dt=Math.min(.06,(ts-(loop.last||ts))/1000);loop.last=ts;clock=ts/1000;let smoke=window.__pondSmoke;if(smoke){smoke.loopCalls=(smoke.loopCalls||0)+1;smoke.lastLoop={ts,dt,view,focused:document.hasFocus(),hidden:document.hidden,beforePhase:game.phase,beforeTimer:game.timer,updateRan:false}}if(view==='fish'&&!document.hidden&&document.hasFocus()){if(smoke)smoke.lastLoop.updateRan=true;game.update(dt,{reel,tap:tapQueued>0});if(smoke){smoke.game={dt,timer:game.timer,phase:game.phase,view,ts,loopCalls:smoke.loopCalls};smoke.lastLoop.afterPhase=game.phase;smoke.lastLoop.afterTimer=game.timer}tapQueued=0;if(game.phase===PHASES.CAUGHT||game.phase===PHASES.ESCAPED){reel=false;if(typeof pointerReel!=='undefined')pointerReel=false;if(typeof keyboardReel!=='undefined')keyboardReel=false}}else{reel=false;tapQueued=0;if(smoke)smoke.lastLoop.afterPhase=game.phase;if(typeof pointerReel!=='undefined')pointerReel=false;if(typeof keyboardReel!=='undefined')keyboardReel=false}telemetry.observe(game);updateSoundFeedback();render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
$('soundBtn').onclick=()=>{soundEnabled=!soundEnabled;$('soundBtn').textContent=soundEnabled?'♫ SFX ON':'♫ SFX OFF';$('soundBtn').setAttribute('aria-pressed',String(soundEnabled));if(soundEnabled){unlockAudio();playSound('tapGood')}};document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>changeView(b.dataset.view));$('castBtn').onclick=()=>{unlockAudio();let before=game.phase,at=performance.now(),tracksBefore={...game.state.hiddenTracks},result=game.cast();if(result){let unlocked=HIDDEN_GOOPS.find(secret=>(tracksBefore[secret.id]||0)<3&&(game.state.hiddenTracks[secret.id]||0)===3&&!game.state.dex[secret.id]?.count);if(unlocked){hiddenReveal={id:unlocked.id,startedAt:performance.now()};playSound('secret')}}if(window.__pondSmoke)window.__pondSmoke.cast={fired:true,before,result,after:game.phase,timer:game.timer,at};reel=false;render()};$('sellBtn').onclick=()=>{let amount=game.reward;if(game.sell())telemetry.resolveCatch('sold',amount);render()};$('keepBtn').onclick=()=>{if(game.keep())telemetry.resolveCatch('kept');render()};$('releaseBtn').onclick=()=>{reel=false;pointerReel=false;activePointerId=null;keyboardReel=false;syncReel();render()};$('tapBtn').onclick=()=>{unlockAudio();tapQueued++};let rb=$('reelBtn'),pointerReel=false,keyboardReel=false,activePointerId=null;const syncReel=()=>{reel=pointerReel||keyboardReel};const down=e=>{if(pointerReel||e.button!==undefined&&e.button!==0)return;e.preventDefault();unlockAudio();pointerReel=true;activePointerId=e.pointerId;syncReel();try{rb.setPointerCapture(e.pointerId)}catch{}};const up=e=>{if(activePointerId!==null&&e?.pointerId!==undefined&&e.pointerId!==activePointerId)return;if(pointerReel&&e)e.preventDefault();pointerReel=false;activePointerId=null;syncReel()};const keyDown=e=>{if(e.code==='Space'||e.code==='Enter'){e.preventDefault();if(!e.repeat){unlockAudio();keyboardReel=true;syncReel()}}};const keyUp=e=>{if(e.code==='Space'||e.code==='Enter'){keyboardReel=false;syncReel()}};rb.addEventListener('pointerdown',down);window.addEventListener('pointerup',up);rb.addEventListener('pointercancel',up);rb.addEventListener('lostpointercapture',up);rb.addEventListener('keydown',keyDown);rb.addEventListener('keyup',keyUp);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>{pointerReel=false;activePointerId=null;keyboardReel=false;syncReel()});document.addEventListener('visibilitychange',()=>{if(document.hidden){pointerReel=false;activePointerId=null;keyboardReel=false;syncReel()}});rb.addEventListener('contextmenu',e=>e.preventDefault());document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>{if(game.setConditions(b.dataset.time,game.state.weather)){conditionsUI();render()}}));document.querySelectorAll('[data-weather]').forEach(b=>b.addEventListener('click',()=>{if(game.setConditions(game.state.timeOfDay,b.dataset.weather)){conditionsUI();render()}}));$('dexSearch').oninput=dexUI;$('dexFilter').onchange=dexUI;const telemetryButton=document.createElement('button');telemetryButton.id='telemetryExport';telemetryButton.className='btn tiny';telemetryButton.textContent='Export session telemetry';telemetryButton.onclick=exportSessionTelemetry;$('specimenLog').before(telemetryButton);render();